package com.carrot.transport;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.lang.ref.WeakReference;
/** Dismissible five-second companion warning; no permanent on-map disconnected banner. */
public final class TransientNotice {
 static final Handler MAIN=new Handler(Looper.getMainLooper());static final ConnectionNoticePolicy policy=new ConnectionNoticePolicy();static WeakReference<Activity> activity=new WeakReference<>(null);static WeakReference<TextView> banner=new WeakReference<>(null);static String message="";static Context app;static final int ID=83012;
 public static void update(Context context,String trip,String text){MAIN.post(()->{app=context.getApplicationContext();long now=SystemClock.elapsedRealtime();if(policy.update(trip,text,now)){message=text;notifyOnce();MAIN.postDelayed(TransientNotice::refresh,5100);}if(text.isEmpty())message="";refresh();});}
 public static void resumed(Activity a){activity=new WeakReference<>(a);refresh();}
 public static void paused(Activity a){if(activity.get()==a){activity.clear();TextView b=banner.get();if(b!=null)b.setVisibility(View.GONE);}}
 public static void refresh(){try{Activity a=activity.get();TextView b=banner.get();boolean visible=!message.isEmpty()&&policy.visible(SystemClock.elapsedRealtime());if(a==null||a.isFinishing()||!visible){if(b!=null)b.setVisibility(View.GONE);return;}if(b==null||b.getContext()!=a){if(b!=null&&b.getParent() instanceof ViewGroup)((ViewGroup)b.getParent()).removeView(b);FrameLayout root=a.findViewById(android.R.id.content);if(root==null)return;b=new TextView(a);b.setTag("kisa-companion-notice");b.setTextColor(Color.WHITE);b.setTextSize(14);float d=a.getResources().getDisplayMetrics().density;b.setPadding(Math.round(14*d),Math.round(12*d),Math.round(14*d),Math.round(12*d));GradientDrawable bg=new GradientDrawable();bg.setColor(0xefa52a24);bg.setCornerRadius(10*d);b.setBackground(bg);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);p.leftMargin=p.rightMargin=Math.round(12*d);p.bottomMargin=Math.round(100*d);root.addView(b,p);banner=new WeakReference<>(b);b.setOnClickListener(v->{policy.dismiss();refresh();if(app!=null)((NotificationManager)app.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ID);});}b.setText(message+"   ×");b.setContentDescription(message+" · 누르면 닫기");b.setVisibility(View.VISIBLE);b.bringToFront();}catch(Exception ignored){}}
 static void notifyOnce(){try{NotificationManager manager=(NotificationManager)app.getSystemService(Context.NOTIFICATION_SERVICE);String channel="kisa_companion_health";manager.createNotificationChannel(new NotificationChannel(channel,"내비 앱 연결 상태",NotificationManager.IMPORTANCE_DEFAULT));Notification.Builder b=new Notification.Builder(app,channel).setSmallIcon(android.R.drawable.stat_notify_error).setContentTitle("내비 앱 연결 확인").setContentText(message).setStyle(new Notification.BigTextStyle().bigText(message)).setAutoCancel(true).setTimeoutAfter(10000);Intent launch=app.getPackageManager().getLaunchIntentForPackage(app.getPackageName());if(launch!=null)b.setContentIntent(PendingIntent.getActivity(app,ID,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));if(Build.VERSION.SDK_INT<33||app.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED)manager.notify(ID,b.build());}catch(Exception ignored){}}
 private TransientNotice(){}
}
